import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers (clinical/stratum features)
    clinical_features = [fid for fid, t in zip(feats.ids, feats.types) if t == 'clinical']
    if not clinical_features:
        clinical_features = list(feats.ids)

    # Find strongest clinical driver by correlation with outcome
    best_driver = None
    best_corr = 0

    for fid in clinical_features:
        col_idx = feats.column(fid)
        corr = np.corrcoef(feats.x[:, col_idx], feats.y.astype(float))[0, 1]
        if abs(corr) > best_corr:
            best_corr = abs(corr)
            best_driver = fid

    # If no strong driver found, return empty design
    if best_corr < 0.1:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features based on correlation with outcome
    selected_features = []
    for fid in feats.ids:
        if fid == best_driver:
            continue
        col_idx = feats.column(fid)
        corr = np.corrcoef(feats.x[:, col_idx], feats.y.astype(float))[0, 1]
        if abs(corr) > 0.05:
            selected_features.append(fid)

    # Remove near-duplicates
    final_features = []
    for fid in selected_features:
        is_duplicate = False
        for existing_fid in final_features:
            if abs(np.corrcoef(feats.x[:, feats.column(fid)], feats.x[:, feats.column(existing_fid)])[0, 1]) > 0.6:
                is_duplicate = True
                break
        if not is_duplicate:
            final_features.append(fid)

    # Limit to 3 features maximum
    final_features = final_features[:3]

    # Create products for top features
    products = []
    if len(final_features) >= 2:
        products.append((final_features[0], final_features[1]))

    # Build loadings from top features
    loadings = {}
    for i, fid in enumerate(final_features):
        col_idx = feats.column(fid)
        corr = np.corrcoef(feats.x[:, col_idx], feats.y.astype(float))[0, 1]
        loadings[fid] = corr

    return Design(
        drivers=(best_driver,) if best_driver else (),
        columns=tuple(final_features),
        products=tuple(products),
        loadings=loadings
    )

